/bin/zsh -lc "python3 - <<'PY'
import json, hashlib
from pathlib import Path
from datetime import datetime
for name in ('regras.md', 'eventos.json'):
    print(name, 'sha256', hashlib.sha256(Path(name).read_bytes()).hexdigest())
events = json.loads(Path('eventos.json').read_text())
unique = {}
duplicates = []
for event in events:
    eid = event['event_id']
    if eid in unique:
        assert unique[eid] == event, f'Duplicata conflitante: {eid}'
        duplicates.append(eid)
    else:
        unique[eid] = event
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
rows = []
channels = {'loja': 0, 'web': 0}
for event in unique.values():
    if event['tipo'] == 'pago' and event['moeda'] == 'BRL' and start <= datetime.fromisoformat(event['em']) < end:
        refunds = [r for r in unique.values() if r['pedido'] == event['pedido'] and r['tipo'] == 'estorno_confirmado' and datetime.fromisoformat(r['em']) < end]
        net = event['valor'] - sum(r['valor'] for r in refunds)
        channels[event['canal']] += net
        rows.append({'pedido': event['pedido'], 'pagamento': event['event_id'], 'bruto': event['valor'], 'estornos': [r['event_id'] for r in refunds], 'estornado': sum(r['valor'] for r in refunds), 'liquido': net, 'canal': event['canal']})
rows.sort(key=lambda row: row['pedido'])
print(json.dumps({'registros':len(events),'eventos_unicos':len(unique),'duplicatas':duplicates,'pedidos':rows,'receita_liquida_centavos':sum(channels.values()),'por_canal_centavos':channels},ensure_ascii=False,indent=2))
PY"

